const tabId = 825319361;
const fruitAndSweetRecipes = await browserjs(tabId, () => {
  const sections = [];
  const h3s = document.querySelectorAll('h3');
  for (const h3 of h3s) {
    if (['Fruits', 'Sweets', 'Elixirs'].some(k => h3.textContent.includes(k))) {
      let el = h3.nextElementSibling;
      const items = [];
      while (el && el.tagName !== 'H3' && el.tagName !== 'H2') {
        if (el.tagName === 'TABLE') {
          items.push(...Array.from(el.querySelectorAll('tr')).map(r => Array.from(r.querySelectorAll('th, td')).map(c => c.textContent.trim()).join(' | ')));
        }
        el = el.nextElementSibling;
      }
      sections.push({ title: h3.textContent.trim(), items: items.slice(0, 25) });
    }
  }
  return sections;
});
console.log(JSON.stringify(fruitAndSweetRecipes, null, 2));

